function ema(vals,p){const k=2/(p+1),o=Array(vals.length).fill(null);let e=null;for(let i=0;i<vals.length;i++){const v=vals[i];if(!Number.isFinite(v))continue;if(e===null){if(i<p-1)continue;const s=vals.slice(i-p+1,i+1);if(s.some(x=>!Number.isFinite(x)))continue;e=s.reduce((a,b)=>a+b,0)/p}else e=v*k+e*(1-k);o[i]=e}return o}
function sma(vals,p){return vals.map((_,i)=>i<p-1?null:vals.slice(i-p+1,i+1).reduce((a,b)=>a+b,0)/p)}
function sd(vals,p){return vals.map((_,i)=>{if(i<p-1)return null;const s=vals.slice(i-p+1,i+1),m=s.reduce((a,b)=>a+b,0)/p;return Math.sqrt(s.reduce((a,b)=>a+(b-m)**2,0)/p)})}
function rsi(vals,p=14){const o=Array(vals.length).fill(null);if(vals.length<=p)return o;let g=0,l=0;for(let i=1;i<=p;i++){const d=vals[i]-vals[i-1];g+=Math.max(d,0);l+=Math.max(-d,0)}g/=p;l/=p;o[p]=l===0?100:100-100/(1+g/l);for(let i=p+1;i<vals.length;i++){const d=vals[i]-vals[i-1];g=(g*(p-1)+Math.max(d,0))/p;l=(l*(p-1)+Math.max(-d,0))/p;o[i]=l===0?100:100-100/(1+g/l)}return o}
function atr(bs,p=14){const t=bs.map((b,i)=>i?Math.max(b.high-b.low,Math.abs(b.high-bs[i-1].close),Math.abs(b.low-bs[i-1].close)):b.high-b.low);return ema(t,p)}
function percentile(a,p){const s=[...a].filter(Number.isFinite).sort((x,y)=>x-y);if(!s.length)return null;return s[Math.min(s.length-1,Math.max(0,Math.round((s.length-1)*p)))]}
function sanitize(bs){return bs.map(b=>{let {high,low}=b;const mid=(b.open+b.close)/2;if((b.volume||0)===0&&mid>0){if(high/mid>1.05)high=Math.max(b.open,b.close)*1.012;if(low/mid<.95)low=Math.min(b.open,b.close)*.988}return {...b,high,low}})}
function indicators(bs){const c=bs.map(b=>b.close),e20=ema(c,20),e50=ema(c,50),r=rsi(c),e12=ema(c,12),e26=ema(c,26),macd=c.map((_,i)=>e12[i]!=null&&e26[i]!=null?e12[i]-e26[i]:null),sig=ema(macd,9),hist=macd.map((v,i)=>v!=null&&sig[i]!=null?v-sig[i]:null),a=atr(bs),m=sma(c,20),s=sd(c,20),bbu=m.map((v,i)=>v!=null?v+2*s[i]:null),bbl=m.map((v,i)=>v!=null?v-2*s[i]:null);let cv=0,pv=0;const vwap=bs.map(b=>{const tp=(b.high+b.low+b.close)/3,vol=b.volume||1;pv+=tp*vol;cv+=vol;return pv/cv});return{e20,e50,r,macd,sig,hist,a,bbu,bbl,vwap}}
function volumeProfile(bs){const s=bs.slice(-120),lo=Math.min(...s.map(b=>b.low)),hi=Math.max(...s.map(b=>b.high));if(!(hi>lo))return null;const bins=16,arr=Array(bins).fill(0);s.forEach(b=>{const p=(b.high+b.low+b.close)/3,i=clamp(Math.floor((p-lo)/(hi-lo)*bins),0,bins-1);arr[i]+=b.volume||1});const idx=arr.indexOf(Math.max(...arr));return lo+(idx+.5)*(hi-lo)/bins}
function patterns(bs){const out=[],n=bs.length-1,b=bs[n],prev=bs[n-1];if(!b||!prev)return out;const body=Math.abs(b.close-b.open),range=Math.max(.0001,b.high-b.low),lower=Math.min(b.open,b.close)-b.low,upper=b.high-Math.max(b.open,b.close);if(body/range<.18)out.push(['Doji',55]);if(lower>body*2.2&&upper<body*1.2)out.push(['Hammer',65]);if(upper>body*2.2&&lower<body*1.2)out.push(['Shooting Star',65]);if(b.close>b.open&&prev.close<prev.open&&b.close>=prev.open&&b.open<=prev.close)out.push(['Bullish Engulfing',72]);if(b.close<b.open&&prev.close>prev.open&&b.open>=prev.close&&b.close<=prev.open)out.push(['Bearish Engulfing',72]);const s=bs.slice(-60),max1=Math.max(...s.slice(0,30).map(x=>x.high)),max2=Math.max(...s.slice(30).map(x=>x.high)),min1=Math.min(...s.slice(0,30).map(x=>x.low)),min2=Math.min(...s.slice(30).map(x=>x.low));if(Math.abs(max1-max2)/b.close<.012)out.push(['Double Top zone',60]);if(Math.abs(min1-min2)/b.close<.012)out.push(['Double Bottom zone',60]);const r20=Math.max(...bs.slice(-21,-1).map(x=>x.high));if(b.close>r20)out.push(['Breakout',78]);const gap=Math.abs(b.open-prev.close)/prev.close;if(gap>.015)out.push([b.open>prev.close?'Gap Up':'Gap Down',70]);const w1=s.slice(-20),w0=s.slice(-40,-20);const rangeNow=Math.max(...w1.map(x=>x.high))-Math.min(...w1.map(x=>x.low)),rangeOld=Math.max(...w0.map(x=>x.high))-Math.min(...w0.map(x=>x.low));if(rangeNow<rangeOld*.68)out.push(['Volatility Contraction',66]);return out.slice(0,7)}
function analyze(bs){
 if(!bs||bs.length<55)return null;const ix=indicators(bs),n=bs.length-1,b=bs[n],look=bs.slice(-30),prev=bs[n-1];const support=percentile(look.map(x=>x.low),.12),resistance=percentile(look.map(x=>x.high),.88),e20=ix.e20[n],e50=ix.e50[n],rv=ix.r[n],mh=ix.hist[n],av=ix.a[n]||b.close*.02;const vols=look.slice(0,-1).map(x=>x.volume).filter(x=>x>0),avgVol=vols.length?vols.reduce((a,x)=>a+x,0)/vols.length:0,volRatio=avgVol&&b.volume?b.volume/avgVol:1;let tech=50,conflicts=[],reasons=[];
 const add=(cond,pts,good,bad)=>{if(cond){tech+=pts;reasons.push(good)}else if(bad)conflicts.push(bad)};
 add(b.close>e20,10,'Price > EMA20','Price below EMA20');add(e20>e50,12,'EMA20 > EMA50','EMA trend conflict');add(rv>=48&&rv<=68,8,'RSI in healthy momentum zone',rv>72?'RSI overbought':rv<42?'RSI weak':null);add(mh>0,9,'MACD histogram positive','MACD negative');add(volRatio>1.15,5,'Volume confirms move','Volume confirmation weak');
 if(b.close>resistance*.997)tech+=6;if(b.close<support*1.01)tech-=6;if(rv>75)tech-=8;if(rv<35)tech-=4;tech=clamp(Math.round(tech),0,100);
 const entry=Math.max(Math.min(b.close,e20?Math.max(e20,support):b.close),support||b.close);const stop=Math.min((support||entry-av)*.998,entry-1.35*av);const risk=Math.max(entry-stop,av*.7);const tp1=entry+1.6*risk,tp2=entry+2.6*risk,rr=(tp2-entry)/(entry-stop);let entryQ=70-Math.abs(b.close-entry)/Math.max(av,.01)*12;if(rv>72)entryQ-=20;if(b.close>resistance&&volRatio<1.1)entryQ-=12;if(rr<1.5)entryQ-=18;entryQ=clamp(Math.round(entryQ),0,100);const rrScore=clamp(Math.round(rr/2.5*100),0,100);const opportunity=clamp(Math.round(.55*tech+.25*entryQ+.20*rrScore),0,100);const poc=volumeProfile(bs);const fibSwing=bs.slice(-60),swingLow=Math.min(...fibSwing.map(x=>x.low)),swingHigh=Math.max(...fibSwing.map(x=>x.high)),fib382=swingHigh-(swingHigh-swingLow)*.382,fib50=swingHigh-(swingHigh-swingLow)*.5,fib618=swingHigh-(swingHigh-swingLow)*.618;const trailATR=b.close-2*av,trailEMA=e20,trailSwing=percentile(bs.slice(-12).map(x=>x.low),.15);const prevClose=prev?.close||b.close,barChange=(b.close-prevClose)/prevClose*100;
 return{bs,ix,n,last:b.close,tech,entryQ,rrScore,opportunity,support,resistance,e20,e50,rsi:rv,macdHist:mh,atr:av,volRatio,entry,stop,tp1,tp2,rr,poc,fib382,fib50,fib618,swingLow,swingHigh,trailATR,trailEMA,trailSwing,patterns:patterns(bs),conflicts:conflicts.filter(Boolean),reasons,barChange}
}
function trendLabel(x){if(!x)return['N/A',''];if(x.tech>=68&&x.last>x.e20)return['Bullish','up'];if(x.tech<=40||x.last<x.e50)return['Bearish','down'];return['Neutral','']}

