let priceChart,rsiChart,macdChart,candle,e20s,e50s,bbus,bbls,vwaps,rsiS,macdH,macdL,sigL,priceLines=[];
function initCharts(){
 const common=()=>({layout:{background:{type:'solid',color:css('--chart')},textColor:css('--muted')},grid:{vertLines:{color:css('--line')},horzLines:{color:css('--line')}},rightPriceScale:{borderColor:css('--line')},timeScale:{borderColor:css('--line'),timeVisible:true,secondsVisible:false},crosshair:{mode:LightweightCharts.CrosshairMode.Normal},handleScroll:true,handleScale:true});
 priceChart=LightweightCharts.createChart($('#priceChart'),common());candle=priceChart.addCandlestickSeries({upColor:css('--green'),downColor:css('--red'),wickUpColor:css('--green'),wickDownColor:css('--red'),borderVisible:false});e20s=priceChart.addLineSeries({color:css('--amber'),lineWidth:2,priceLineVisible:false,lastValueVisible:false});e50s=priceChart.addLineSeries({color:css('--purple'),lineWidth:2,priceLineVisible:false,lastValueVisible:false});bbus=priceChart.addLineSeries({color:css('--cyan'),lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false});bbls=priceChart.addLineSeries({color:css('--cyan'),lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false});vwaps=priceChart.addLineSeries({color:css('--accent'),lineWidth:1,priceLineVisible:false,lastValueVisible:false});
 rsiChart=LightweightCharts.createChart($('#rsiChart'),{...common(),rightPriceScale:{borderColor:css('--line'),scaleMargins:{top:.1,bottom:.1}}});rsiS=rsiChart.addLineSeries({color:css('--accent'),lineWidth:2,priceLineVisible:false});rsiS.createPriceLine({price:70,color:css('--red'),lineStyle:2,lineWidth:1,axisLabelVisible:true,title:'70'});rsiS.createPriceLine({price:30,color:css('--green'),lineStyle:2,lineWidth:1,axisLabelVisible:true,title:'30'});
 macdChart=LightweightCharts.createChart($('#macdChart'),common());macdH=macdChart.addHistogramSeries({priceScaleId:'',priceFormat:{type:'price',precision:3,minMove:.001}});macdL=macdChart.addLineSeries({color:css('--accent'),lineWidth:2,priceLineVisible:false});sigL=macdChart.addLineSeries({color:css('--amber'),lineWidth:1,priceLineVisible:false});
 [[priceChart,$('#priceChart')],[rsiChart,$('#rsiChart')],[macdChart,$('#macdChart')]].forEach(([c,e])=>new ResizeObserver(x=>c.applyOptions({width:x[0].contentRect.width})).observe(e));
}
function applyChartTheme(){if(!priceChart)return;const o={layout:{background:{type:'solid',color:css('--chart')},textColor:css('--muted')},grid:{vertLines:{color:css('--line')},horzLines:{color:css('--line')}},rightPriceScale:{borderColor:css('--line')},timeScale:{borderColor:css('--line')}};[priceChart,rsiChart,macdChart].forEach(c=>c.applyOptions(o));candle.applyOptions({upColor:css('--green'),downColor:css('--red'),wickUpColor:css('--green'),wickDownColor:css('--red')});e20s.applyOptions({color:css('--amber')});e50s.applyOptions({color:css('--purple')});bbus.applyOptions({color:css('--cyan')});bbls.applyOptions({color:css('--cyan')});vwaps.applyOptions({color:css('--accent')})}
