function holdingFor(sym){return paper.find(x=>x.status==='open'&&x.symbol===sym)||portfolio.find(x=>x.symbol===sym)}
function actionModel(){
 const held=holdingFor(symbol),over=A.rsi>72,nearRes=A.last>A.resistance*.985,mtfBull=Object.values(mtf).filter(x=>x?.analysis?.tech>=65).length,mtfBear=Object.values(mtf).filter(x=>x?.analysis?.tech<=40).length;
 let code='WAIT',cls='warn',titleTh='WAIT FOR ENTRY — รอจังหวะ',titleEn='WAIT FOR ENTRY',copyTh='โครงสร้างยังไม่ให้ความได้เปรียบมากพอ จึงควรรอราคาเข้าเงื่อนไขก่อน',copyEn='The current setup does not yet offer enough edge; wait for a trigger.';
 if(held&&A.last<=A.stop){code='CUT',cls='sell',titleTh='CUT LOSS — ตัดความเสี่ยง',titleEn='CUT LOSS',copyTh='ราคาหลุดจุด invalidation ของแผนแล้ว ความเสี่ยงสำคัญกว่าการรอเด้ง',copyEn='Price has broken the plan invalidation level; risk control takes priority.'}
 else if(held&&A.last>=A.tp1){code='TAKE',cls='buy',titleTh='TAKE PARTIAL PROFIT — ล็อกกำไรบางส่วน',titleEn='TAKE PARTIAL PROFIT',copyTh='ราคาแตะเป้ากำไรแรกแล้ว เหมาะกับการลดบางส่วนและเลื่อน trailing stop',copyEn='Price reached the first target; consider trimming and tightening the trailing stop.'}
 else if(held&&A.tech>=65){code='HOLD',cls='buy',titleTh='HOLD / ADD ON PULLBACK',titleEn='HOLD / ADD ON PULLBACK',copyTh='แนวโน้มยังเป็นบวก แต่การเพิ่มควรรอจังหวะย่อหรือ breakout ที่มี volume ยืนยัน',copyEn='Trend remains constructive; add only on a controlled pullback or volume-confirmed breakout.'}
 else if(!held&&A.opportunity>=76&&A.rr>=1.6&&!over&&mtfBull>=3){code='BUY',cls='buy',titleTh='BUY SMALL — เข้าไม้แรก',titleEn='BUY SMALL',copyTh='หลาย timeframe สนับสนุนและ R:R ผ่านเกณฑ์ แต่เริ่มด้วยขนาดเล็กเพื่อให้ stop คุมความเสี่ยง',copyEn='Multiple timeframes agree and R:R is acceptable; start small so the stop defines risk.'}
 else if(over&&A.tech>=60){code='NOCHASE',cls='warn',titleTh='DO NOT CHASE — อย่าไล่ราคา',titleEn='DO NOT CHASE',copyTh='แนวโน้มดีแต่ RSI ร้อนและราคาห่างจุดเข้า รอ pullback หรือฐานใหม่จะได้ R:R ดีกว่า',copyEn='Trend is positive but RSI is hot and price is stretched; wait for a pullback or new base.'}
 else if(A.tech<=35||mtfBear>=4){code='AVOID',cls='sell',titleTh='AVOID / REDUCE — ยังไม่ควรเข้าใหม่',titleEn='AVOID / REDUCE',copyTh='แนวโน้มและ momentum ยังอ่อน การรีบซื้อเป็นการรับความเสี่ยงที่ยังไม่จำเป็น',copyEn='Trend and momentum remain weak; a new entry would take unnecessary risk.'}
 else if(nearRes&&A.volRatio<1.1){code='WAIT',cls='warn',titleTh='WAIT FOR BREAKOUT CONFIRMATION',titleEn='WAIT FOR BREAKOUT CONFIRMATION',copyTh='ราคาใกล้แนวต้านแต่ volume ยังไม่ยืนยัน รอปิดเหนือแนวต้านพร้อม volume ก่อน',copyEn='Price is near resistance without strong volume; wait for a confirmed close above it.'}
 return{code,cls,title:lang==='th'?titleTh:titleEn,copy:lang==='th'?copyTh:copyEn};
}
function renderDecision(){if(!A)return;const action=actionModel();setText('#symbolTitle',symbol);setText('#marketBadge',`${meta.fullExchangeName||meta.exchange||'US'} · ${meta.currency||'USD'}`);setText('#lastPrice',usd(A.last));const pc=meta.previousClose?((A.last-meta.previousClose)/meta.previousClose*100):A.barChange;setText('#change',pct(pc));$('#change').className=pc>=0?'up':'down';const conf=clamp(Math.round((A.opportunity+consensusPercent())/2),0,100);setText('#confidence',conf);$('#confidenceRing').style.background=`conic-gradient(${css('--accent')} 0 ${conf}%,${css('--line')} ${conf}% 100%)`;const p=$('#actionPill');p.textContent=action.title;p.className=`action-pill ${action.cls}`;setText('#actionCopy',action.copy);
 const reason=A.reasons.slice(0,2).join(' + ')||'Mixed technical evidence';setText('#whyNow',lang==='th'?translateReason(reason):reason);setText('#invalidation',`${lang==='th'?'หลุด':'Below'} ${usd(A.stop)}`);const s=calcSizing().balanced;setText('#quickSize',s.shares?`${fmt(s.shares,s.fractional?2:0)} ${lang==='th'?'หุ้น':'shares'} · ${thb(s.valueThb)}`:'0');let wait= A.last<A.resistance?`${lang==='th'?'รอปิดเหนือ':'Close above'} ${usd(A.resistance)}`:`${lang==='th'?'รอ retest':'Wait for retest'} ${usd(A.entry)}`;if(A.rsi>72)wait=`RSI < 68 / pullback ${usd(A.e20)}`;setText('#waitFor',wait);
 const fundScore=getFundScore();const overall=Math.round(.55*A.opportunity+.2*fundScore+.25*consensusPercent());setText('#opportunityScore',overall);setScore('#technicalScore','#barTech',A.tech);setScore('#entryScore','#barEntry',A.entryQ);setScore('#rrScore','#barRR',A.rrScore);setScore('#fundScore','#barFund',fundScore);const conflicts=[...A.conflicts];if(A.rr<1.5)conflicts.push('R:R < 1.5');if(A.volRatio<1)conflicts.push('Low volume');if(A.rsi>72)conflicts.push('Overbought');$('#conflictList').innerHTML=(conflicts.length?conflicts:['No major conflict']).slice(0,6).map(x=>`<i>${escapeHtml(x)}</i>`).join('');renderMTF();
}
function translateReason(s){return s.replace('Price > EMA20','ราคาเหนือ EMA20').replace('EMA20 > EMA50','EMA20 เหนือ EMA50').replace('RSI in healthy momentum zone','RSI อยู่โซน momentum ที่ดี').replace('MACD histogram positive','MACD เป็นบวก').replace('Volume confirms move','Volume ยืนยันการเคลื่อนไหว')}
function setScore(id,bar,v){setText(id,Math.round(v));$(bar).style.width=`${clamp(v,0,100)}%`}
function consensusPercent(){const vals=Object.values(mtf).map(x=>x.analysis).filter(Boolean);if(!vals.length)return 50;return Math.round(vals.reduce((a,x)=>a+x.tech,0)/vals.length)}
function renderMTF(){const order=['5m','15m','1h','4h','1d','1w'];$('#mtfGrid').innerHTML=order.map(k=>{const x=mtf[k]?.analysis,[lab,cl]=trendLabel(x);return `<div class="mtf-item"><span>${k.toUpperCase()}</span><b class="${cl}">${lab}</b><span>${x?x.tech:'—'}/100</span></div>`}).join('');const c=consensusPercent();setText('#consensusBadge',`${c}% ${c>=60?'Bullish':c<=42?'Bearish':'Mixed'}`);$('#consensusBadge').className='badge '+(c>=60?'up':c<=42?'down':'')}
function renderScenarios(){if(!A)return;const rows=[
 ['B',lang==='th'?'Breakout':'Breakout',lang==='th'?`ถ้าปิดเหนือ ${usd(A.resistance)} และ Volume > 1.2× → เข้า 30% ของขนาดเป้าหมาย`:`If price closes above ${usd(A.resistance)} with volume >1.2× → enter 30% of target size`],
 ['P',lang==='th'?'Pullback':'Pullback',lang==='th'?`ถ้าย่อบริเวณ EMA20 ${usd(A.e20)} แล้วไม่หลุด ${usd(A.support)} → เพิ่มได้อีก 30%`:`If price pulls back near EMA20 ${usd(A.e20)} and holds ${usd(A.support)} → add another 30%`],
 ['D',lang==='th'?'Breakdown':'Breakdown',lang==='th'?`ถ้าหลุด ${usd(A.stop)} → ยกเลิกแผนซื้อ / ตัดขาดทุน`:`If price breaks ${usd(A.stop)} → cancel the long setup / exit`]
 ];$('#scenarioList').innerHTML=rows.map(r=>`<div class="scenario"><i>${r[0]}</i><div><b>${r[1]}</b><p>${r[2]}</p></div></div>`).join('');setText('#rrBadge',`R:R 1:${fmt(A.rr,2)}`)}
function calcSizing(){if(!A)return{conservative:{},balanced:{},aggressive:{}};const capital=Math.max(0,+$('#capital').value||100000),priceThb=A.entry*fx,perShareRisk=(A.entry-A.stop)*fx;const mk=(riskPct,allocPct,fractional=false)=>{const riskBudget=capital*riskPct/100,byRisk=perShareRisk>0?riskBudget/perShareRisk:0,byAlloc=priceThb>0?capital*allocPct/100/priceThb:0;let shares=Math.min(byRisk,byAlloc);shares=fractional?Math.floor(shares*100)/100:Math.floor(shares);return{shares,valueThb:shares*priceThb,worstLoss:shares*perShareRisk,riskPct,allocPct,fractional}};return{conservative:mk(.5,15,false),balanced:mk(1,25,false),aggressive:mk(1.5,40,true)}}
function renderSizing(){if(!A)return;const x=calcSizing();$('#sizeModes').innerHTML=[['Conservative',x.conservative],['Balanced',x.balanced],['Aggressive',x.aggressive]].map(([n,s])=>`<div class="size-mode"><span>${n}</span><b>${fmt(s.shares,s.fractional?2:0)} ${lang==='th'?'หุ้น':'sh.'}</b><small>${thb(s.valueThb)} · ${lang==='th'?'เสี่ยง':'risk'} ${thb(s.worstLoss)}</small></div>`).join('')}
$('#capital').addEventListener('input',()=>{renderSizing();renderDecision()});
function renderScalePlan(){if(!A)return;const b=calcSizing().balanced.shares||0;const r=[['ENTRY 40%',A.entry,b*.4],['BREAKOUT 30%',Math.max(A.resistance,A.last),b*.3],['RETEST 30%',A.e20,b*.3],['TP1 -30%',A.tp1,-b*.3],['TP2 -40%',A.tp2,-b*.4],['TRAIL 30%',Math.max(A.trailATR,A.trailEMA),-b*.3]];$('#scalePlan').innerHTML=r.map(x=>`<div class="timeline-row"><span>${x[0]}</span><b>${usd(x[1])}</b><strong class="${x[2]>=0?'up':'down'}">${x[2]>=0?'+':''}${fmt(x[2],1)} sh</strong></div>`).join('')}
function renderLevels(){if(!A)return;const rows=[['Support',A.support],['Resistance',A.resistance],['EMA20',A.e20],['EMA50',A.e50],['VWAP',ind.vwap?.[A.n]],['Volume POC',A.poc],['Fib 0.382',A.fib382],['Fib 0.500',A.fib50],['Fib 0.618',A.fib618],['Entry',A.entry],['Stop',A.stop],['TP1',A.tp1],['TP2',A.tp2]];$('#levels').innerHTML=rows.map(x=>`<div class="level"><span>${x[0]}</span><b>${usd(x[1])}</b></div>`).join('')}
function renderPatterns(){if(!A)return;const tags=A.patterns.length?A.patterns:[['No high-confidence pattern',50]];$('#patternList').innerHTML=tags.map(x=>`<span class="tag">${escapeHtml(x[0])} · ${x[1]}%</span>`).join('')}
function renderTrailing(){if(!A)return;$('#trailStops').innerHTML=[['ATR ×2',A.trailATR],['EMA20',A.trailEMA],['Swing-low',A.trailSwing],['Recommended',Math.max(A.trailATR,A.trailEMA,A.trailSwing||0)]].map(x=>`<div class="level"><span>${x[0]}</span><b>${usd(x[1])}</b></div>`).join('')}

function daysTo(ts){return Number.isFinite(+ts)?Math.ceil((+ts*1000-now())/day):null}
function renderEvents(){const arr=[];const e=daysTo(fundamental.earningsDate),d=daysTo(fundamental.exDividendDate);if(market.events?.length){const ev=market.events[0];arr.push(['Macro',lang==='th'?`เหตุการณ์เศรษฐกิจสำคัญ: ${ev.event}${ev.time?' · '+ev.time:''}`:`Key macro event: ${ev.event}${ev.time?' · '+ev.time:''}`])}if(e!=null&&e>=0&&e<=14)arr.push([e<=3?'High':'Medium',lang==='th'?`Earnings ใน ${e} วัน — ลด position size และระวัง gap`:`Earnings in ${e} days — reduce size and expect gap risk`]);if(d!=null&&d>=0&&d<=14)arr.push(['Info',lang==='th'?`Ex-dividend ใน ${d} วัน`:`Ex-dividend in ${d} days`]);if(market.vix>25)arr.push(['High',lang==='th'?`VIX ${fmt(market.vix,1)}: ตลาดผันผวนสูง ควรลด risk ต่อดีล`:`VIX ${fmt(market.vix,1)}: high-volatility regime, reduce trade risk`]);if(market.regime==='Risk-Off')arr.push(['High',lang==='th'?'ตลาดอยู่ใน Risk-Off — signal long ควรใช้เงื่อนไขเข้มขึ้น':'Market is Risk-Off — require stronger confirmation for longs']);if(!arr.length)arr.push(['Normal',lang==='th'?'ยังไม่พบ corporate / volatility warning สำคัญจาก public feed':'No major corporate/volatility warning detected from the public feed']);$('#eventWarnings').innerHTML=arr.map(x=>`<div class="warning"><b>${x[0]}</b><p>${escapeHtml(x[1])}</p></div>`).join('')}

function scoreFund(f){if(!f||f.error)return 50;let s=50;if(f.revenueGrowth>0.1)s+=10;else if(f.revenueGrowth<0)s-=10;if(f.earningsGrowth>0.1)s+=10;else if(f.earningsGrowth<0)s-=10;if(f.profitMargins>0.15)s+=8;if(f.freeCashflow>0)s+=7;if(f.debtToEquity!=null&&f.debtToEquity<100)s+=5;if(f.trailingPE!=null&&f.trailingPE>60)s-=8;if(f.forwardPE!=null&&f.trailingPE!=null&&f.forwardPE<f.trailingPE)s+=5;return clamp(Math.round(s),0,100)}
function getFundScore(){return scoreFund(fundamental)}
function renderFundamentals(){const s=getFundScore();setText('#fundBadge',`${s}/100`);const f=fundamental||{};$('#fundamentalBody').innerHTML=[['Revenue growth',f.revenueGrowth!=null?pct(f.revenueGrowth*100):'—'],['Earnings growth',f.earningsGrowth!=null?pct(f.earningsGrowth*100):'—'],['Profit margin',f.profitMargins!=null?pct(f.profitMargins*100):'—'],['Trailing P/E',fmt(f.trailingPE)],['Forward P/E',fmt(f.forwardPE)],['Debt / Equity',fmt(f.debtToEquity)],['Free cash flow',f.freeCashflow!=null?`$${fmt(f.freeCashflow/1e9,2)}B`:'—'],['Analyst target',usd(f.targetMeanPrice)],['Consensus',f.recommendationKey||'—']].map(x=>`<div class="metric-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function sentiment(title){const s=title.toLowerCase(),pos=['beat','surge','record','upgrade','growth','profit','strong','launch','wins','rally','raises','bullish'],neg=['miss','cuts','downgrade','lawsuit','probe','decline','weak','recall','falls','plunge','bearish','risk'];let v=0;pos.forEach(x=>{if(s.includes(x))v++});neg.forEach(x=>{if(s.includes(x))v--});return v>0?'Positive':v<0?'Negative':'Neutral'}
function classifyNews(title){const s=title.toLowerCase();if(/earnings|revenue|profit|eps/.test(s))return'Earnings';if(/lawsuit|probe|regulat|antitrust/.test(s))return'Regulation';if(/launch|product|iphone|chip|ai/.test(s))return'Product';if(/upgrade|downgrade|target/.test(s))return'Analyst';return'Macro/Company'}
function renderNews(){if(!news.length){$('#newsList').innerHTML=`<div class="small">${lang==='th'?'ยังไม่มีข่าวจาก public feed':'No news from public feed'}</div>`;return}$('#newsList').innerHTML=news.slice(0,9).map(n=>{const s=sentiment(n.title);return`<div class="news-item"><div><div class="sent ${s==='Positive'?'up':s==='Negative'?'down':''}">${s}</div><p>${classifyNews(n.title)}</p></div><div><b>${escapeHtml(n.title)}</b><p>${escapeHtml(n.publisher)} · ${n.published?new Date(n.published*1000).toLocaleString():''}</p></div></div>`}).join('')}
function explainMove(){const daily=mtf['1d']?.analysis,chg=daily?.barChange??A?.barChange??0,qqq=market.qqqChange??0,ratio=A?.volRatio??1;const sn=news.map(n=>sentiment(n.title)),pos=sn.filter(x=>x==='Positive').length,neg=sn.filter(x=>x==='Negative').length;let parts=[];parts.push(lang==='th'?`${symbol} เคลื่อนไหว ${pct(chg)} ในแท่งล่าสุดของกรอบรายวัน`:`${symbol} moved ${pct(chg)} on the latest daily bar`);parts.push(lang==='th'?`เทียบ QQQ ${pct(qqq)} จึง ${chg>qqq?'แข็งกว่าตลาด':'อ่อนกว่าตลาด'}`:`versus QQQ ${pct(qqq)}, so it is ${chg>qqq?'outperforming':'underperforming'} the growth benchmark`);parts.push(lang==='th'?`Volume ratio ≈ ${fmt(ratio,2)}× ${ratio>1.2?'มีแรงยืนยัน':'ยังไม่เด่น'}`:`Volume ratio ≈ ${fmt(ratio,2)}×, ${ratio>1.2?'confirming the move':'not strongly confirming the move'}`);parts.push(lang==='th'?`ข่าวล่าสุด: Positive ${pos} / Negative ${neg}`:`Recent news: ${pos} positive / ${neg} negative`);$('#moveExplain').textContent=parts.join(' · ')}
$('#explainMoveBtn').onclick=explainMove;

async function loadFundNews(){const [f,n]=await Promise.all([jfetch(`/api/fundamentals?symbol=${encodeURIComponent(symbol)}`).catch(()=>({error:true})),jfetch(`/api/news?symbol=${encodeURIComponent(symbol)}`).catch(()=>({news:[]}))]);fundamental=f||{};news=n.news||[];renderFundamentals();renderNews();renderEvents();renderDecision()}
async function loadFX(){try{const j=await jfetch('/api/fx');if(Number.isFinite(+j.rate))fx=+j.rate;setText('#fxRateTop',fmt(fx,2));renderSizing();renderPortfolio()}catch{setText('#fxRateTop',fmt(fx,2))}}
async function fetchChart(sym,interval){const j=await jfetch(`/api/chart?symbol=${encodeURIComponent(sym)}&interval=${encodeURIComponent(interval)}`,16000);if(j.error)throw new Error(j.error);j.bars=sanitize(j.bars||[]);return j}
async function loadMTF(){const ints=['5m','15m','1h','4h','1d','1w'];const out=await Promise.all(ints.map(async k=>{try{const j=await fetchChart(symbol,k);return[k,{...j,analysis:analyze(j.bars)}]}catch{return[k,{analysis:null}]} }));mtf=Object.fromEntries(out);renderMTF();renderDecision();loadRelative();}
async function loadCurrent(){setStatus(T('loading'));symbol=$('#search').value.trim().toUpperCase()||symbol;store('tensai-symbol',symbol);$('#search').value=symbol;try{const j=await fetchChart(symbol,$('#interval').value);bars=j.bars;meta=j.meta||{};ind=indicators(bars);A=analyze(bars);if(!A)throw new Error('Not enough market data');renderCharts();renderLevels();renderPatterns();renderTrailing();renderDecision();renderScenarios();renderSizing();renderScalePlan();setStatus(T('live'),true);checkAlerts();recordSignal();}catch(e){setStatus('Data unavailable');toast(`Market data: ${e.message}`)}}
async function analyzeAll(){await Promise.all([loadCurrent(),loadFX()]);await Promise.all([loadMTF(),loadFundNews(),loadMarketContext()]);renderDecision();renderEvents()}
$('#analyzeBtn').onclick=analyzeAll;$('#refreshBtn').onclick=analyzeAll;$('#interval').onchange=loadCurrent;

$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);const q=$('#search').value.trim();if(q.length<1){$('#suggest').classList.remove('show');return}searchTimer=setTimeout(async()=>{try{const j=await jfetch(`/api/search?q=${encodeURIComponent(q)}`);const list=j.results||j.quotes||[];$('#suggest').innerHTML=list.slice(0,8).map(x=>`<button data-sym="${escapeHtml(x.symbol)}"><b>${escapeHtml(x.symbol)}</b><span>${escapeHtml(x.name||x.shortname||x.longname||x.exchange||'')}</span></button>`).join('');$('#suggest').classList.toggle('show',list.length>0);$$('#suggest button').forEach(b=>b.onclick=()=>{symbol=b.dataset.sym;$('#search').value=symbol;$('#suggest').classList.remove('show');analyzeAll()})}catch{$('#suggest').classList.remove('show')}},250)});
$('#search').addEventListener('keydown',e=>{if(e.key==='Enter'){symbol=$('#search').value.trim().toUpperCase();$('#suggest').classList.remove('show');analyzeAll()}});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#suggest').classList.remove('show')});

async function loadMarketContext(){try{const [j,ev]=await Promise.all([jfetch(`/api/batch?symbols=${encodeURIComponent(sectorEtfs.concat(['^VIX']).join(','))}`,18000),jfetch('/api/events',12000).catch(()=>({events:[]}))]),q=j.quotes||[];market.events=ev.events||[];market.heat=q.filter(x=>!x.error);const v=q.find(x=>x.symbol==='^VIX');market.vix=v?.price;market.qqqChange=q.find(x=>x.symbol==='QQQ')?.change||0;market.spyChange=q.find(x=>x.symbol==='SPY')?.change||0;market.regime=(market.vix>25||(market.spyChange<-.8&&market.qqqChange<-1))?'Risk-Off':(market.vix<20&&market.spyChange>0&&market.qqqChange>0)?'Bull Trend':market.vix>22?'High Volatility':'Sideways / Mixed';renderRegime();renderHeatmap();renderEvents()}catch{} }
function renderRegime(){setText('#regimeBadge',market.regime||'—');$('#regimeBody').innerHTML=[['Regime',market.regime||'—'],['VIX',fmt(market.vix,1)],['SPY today',pct(market.spyChange)],['QQQ today',pct(market.qqqChange)],['Signal weighting',market.regime==='Risk-Off'?'Stricter entries / smaller size':market.regime==='Bull Trend'?'Trend-following favored':'Balanced / wait for confirmation']].map(x=>`<div class="metric-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function renderHeatmap(){if(!market.heat)return;$('#heatmap').innerHTML=market.heat.filter(x=>sectorNames[x.symbol]).map(x=>`<div class="heat ${x.change>=0?'pos':'neg'}"><div><strong>${x.symbol}</strong><small>${sectorNames[x.symbol]}</small></div><b>${pct(x.change)}</b></div>`).join('')}
async function loadRelative(){try{const stock=mtf['1d']?.bars||[],[s,q]=await Promise.all([fetchChart('SPY','1d'),fetchChart('QQQ','1d')]);const ret=x=>x.length>20?(x.at(-1).close/x.at(-21).close-1)*100:null,rs=ret(stock),rsp=ret(s.bars),rq=ret(q.bars);market.rel={stock:rs,spy:rsp,qqq:rq};$('#relativeBody').innerHTML=[['20D '+symbol,pct(rs)],['20D SPY',pct(rsp)],['20D QQQ',pct(rq)],['vs SPY',pct(rs-rsp)],['vs QQQ',pct(rs-rq)]].map(x=>`<div class="metric-row"><span>${x[0]}</span><b class="${String(x[1]).startsWith('+')?'up':''}">${x[1]}</b></div>`).join('')}catch{}}

function scanScore(a,mode){if(!a)return-999;if(mode==='buy')return a.opportunity;if(mode==='breakout')return 100-Math.abs(a.resistance-a.last)/a.atr*20+(a.tech-50);if(mode==='oversold')return (45-a.rsi)*2+(a.last<a.e20?15:0)+(a.macdHist>0?20:0);if(mode==='momentum')return a.tech+(a.volRatio>1.2?10:0);if(mode==='avoid')return 100-a.tech+(a.rsi>75?10:0);return a.opportunity}
async function scan(){const btn=$('#scanBtn');btn.disabled=true;btn.textContent='Scanning…';const syms=[...new Set([symbol,...portfolio.map(x=>x.symbol),...universe])].slice(0,22);const mode=$('#scannerMode').value;const rows=[];for(let i=0;i<syms.length;i+=5){const batch=await Promise.all(syms.slice(i,i+5).map(async s=>{try{const j=await fetchChart(s,'1d'),a=analyze(j.bars);return{s,a}}catch{return null}}));batch.filter(Boolean).forEach(x=>rows.push(x))}rows.sort((a,b)=>scanScore(b.a,mode)-scanScore(a.a,mode));$('#scannerTable').innerHTML=`<table><thead><tr><th>Symbol</th><th>Action</th><th>Opportunity</th><th>RSI</th><th>R:R</th><th>Near S/R</th><th></th></tr></thead><tbody>${rows.slice(0,18).map(x=>{const ac=x.a.opportunity>=72?'BUY SETUP':x.a.tech<=38?'AVOID':x.a.rsi>72?'NO CHASE':'WAIT';const dist=(x.a.resistance-x.a.last)/x.a.last*100;return`<tr><td><b>${x.s}</b></td><td>${ac}</td><td>${x.a.opportunity}</td><td>${fmt(x.a.rsi,1)}</td><td>1:${fmt(x.a.rr,2)}</td><td>${pct(-dist)} to R</td><td><button data-open="${x.s}">Open</button></td></tr>`}).join('')}</tbody></table>`;$$('[data-open]').forEach(b=>b.onclick=()=>{symbol=b.dataset.open;$('#search').value=symbol;$$('.tab')[0].click();analyzeAll()});btn.disabled=false;btn.textContent='Scan'}
$('#scanBtn').onclick=scan;
function renderAlerts(){$('#alerts').innerHTML=alerts.length?alerts.map((a,i)=>`<div class="alert-item"><span>${escapeHtml(a.text)}</span><button data-del-alert="${i}">×</button></div>`).join(''):`<div class="small">${lang==='th'?'ยังไม่มี Alert':'No alerts yet'}</div>`;$$('[data-del-alert]').forEach(b=>b.onclick=()=>{alerts.splice(+b.dataset.delAlert,1);store('tensai-alerts',alerts);renderAlerts()})}
$('#addAlert').onclick=()=>{const text=$('#alertText').value.trim();if(!text)return;alerts.push({text,created:now(),fired:false});store('tensai-alerts',alerts);$('#alertText').value='';renderAlerts();toast('Alert added')};
$('#enableNotify').onclick=async()=>{if('Notification'in window){const p=await Notification.requestPermission();toast(`Notifications: ${p}`)}};
function alertSymbol(text){const m=text.toUpperCase().match(/\b[A-Z]{1,5}\b/g)||[];return m.find(x=>universe.includes(x)||x===symbol)||symbol}
function checkAlerts(){alerts.forEach(a=>{if(a.fired)return;const sym=alertSymbol(a.text);if(sym!==symbol)return;const s=a.text.toLowerCase();let hit=false;if(/buy setup|ซื้อ|buy/.test(s)&&A.opportunity>=72)hit=true;const rm=s.match(/rsi\s*<\s*(\d+)/);if(rm&&A.rsi<+rm[1])hit=true;if(/breakout|ทะลุ/.test(s)&&A.last>A.resistance)hit=true;if(/support|แนวรับ/.test(s)&&Math.abs(A.last-A.support)<A.atr)hit=true;if(hit){a.fired=true;toast(`Alert: ${a.text}`);if(Notification.permission==='granted')new Notification('Tensai Trading Alert',{body:a.text})}});store('tensai-alerts',alerts);renderAlerts()}

function modal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
$('#modalClose').onclick=()=>$('#modal').classList.add('hidden');$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').classList.add('hidden')};
$('#addHolding').onclick=()=>{modal(`<h3>${lang==='th'?'เพิ่มหุ้นในพอร์ต':'Add holding'}</h3><div class="form-grid" style="margin-top:15px"><label>Symbol<input id="mSym" value="${symbol}"></label><label>Shares<input id="mShares" type="number" step="0.01" value="1"></label><label>Avg price USD<input id="mAvg" type="number" step="0.01" value="${fmt(A?.last||0,2)}"></label><label>FX entry<input id="mFx" type="number" step="0.01" value="${fmt(fx,2)}"></label></div><button id="saveHolding" class="primary" style="margin-top:12px">Save</button>`);$('#saveHolding').onclick=()=>{const h={symbol:$('#mSym').value.trim().toUpperCase(),shares:+$('#mShares').value,avgUsd:+$('#mAvg').value,fxEntry:+$('#mFx').value};if(h.symbol&&h.shares>0){portfolio.push(h);store('tensai-portfolio',portfolio);$('#modal').classList.add('hidden');refreshPortfolioPrices()}}};
function renderHoldings(){$('#holdings').innerHTML=portfolio.length?portfolio.map((h,i)=>`<div class="holding"><div><b>${h.symbol}</b> · ${fmt(h.shares,2)} sh · avg ${usd(h.avgUsd)}</div><button data-hdel="${i}">Remove</button></div>`).join(''):`<div class="small">${lang==='th'?'เพิ่มหุ้นเพื่อให้ระบบวิเคราะห์ concentration, stress และผลตอบแทนเงินบาท':'Add holdings for concentration, stress and THB-return analysis.'}</div>`;$$('[data-hdel]').forEach(b=>b.onclick=()=>{portfolio.splice(+b.dataset.hdel,1);store('tensai-portfolio',portfolio);renderPortfolio()})}
async function refreshPortfolioPrices(){if(!portfolio.length){renderPortfolio();return}try{const j=await jfetch(`/api/batch?symbols=${encodeURIComponent(portfolio.map(x=>x.symbol).join(','))}`,18000);const q=j.quotes||[];portfolio.forEach(h=>{const x=q.find(z=>z.symbol===h.symbol);if(x&&!x.error){h.price=x.price;h.change=x.change}});store('tensai-portfolio',portfolio);renderPortfolio();loadCorrelations()}catch{renderPortfolio()}}
function renderPortfolio(){renderHoldings();const val=portfolio.reduce((a,h)=>a+(h.price||h.avgUsd||0)*h.shares*fx,0),cost=portfolio.reduce((a,h)=>a+h.avgUsd*h.shares*(h.fxEntry||fx),0),pnl=val-cost,cash=Math.max(0,(+$('#capital').value||100000)-val);$('#portfolioSummary').innerHTML=[['Value',thb(val)],['P&L',thb(pnl)],['Cash',thb(cash)],['USD exposure',`${val?fmt(val/(val+cash)*100,0):0}%`]].map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');renderStress(val);renderConcentration();renderTHBReturn()}
function renderStress(val){const scenarios=[['Best',val*1.05*1.01,'good'],['Base',val,''],['Nasdaq -3%',val*.964,'bad'],['Stops + FX -2%',val*.93,'bad']];const max=Math.max(...scenarios.map(x=>x[1]),1);$('#stressBars').innerHTML=scenarios.map(x=>`<div class="stress-row ${x[2]}"><span>${x[0]}</span><i><em style="width:${x[1]/max*100}%"></em></i><b>${thb(x[1])}</b></div>`).join('');setText('#stressNotes',lang==='th'?'เป็น scenario estimate ไม่ใช่ VaR ทางสถิติ; ใช้เพื่อเห็น downside แบบเร็ว':'Scenario estimate, not statistical VaR; intended for quick downside awareness.')}
function renderConcentration(){const total=portfolio.reduce((a,h)=>a+(h.price||h.avgUsd)*h.shares,0),by={};portfolio.forEach(h=>{const s=sectors[h.symbol]||'Other';by[s]=(by[s]||0)+(h.price||h.avgUsd)*h.shares});const top=Object.entries(by).sort((a,b)=>b[1]-a[1])[0];$('#corrBody').innerHTML=[['Largest sector',top?`${top[0]} ${fmt(top[1]/Math.max(total,1)*100,0)}%`:'—'],['Holdings',portfolio.length],['Avg pair correlation',market.avgCorr!=null?fmt(market.avgCorr,2):'—'],['Portfolio note',top&&top[1]/total>.55?'High concentration — new same-sector buys should be smaller':'Diversification acceptable from current inputs']].map(x=>`<div class="metric-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function renderTHBReturn(){let stockP=0,fxP=0,w=0;portfolio.forEach(h=>{const p=h.price||h.avgUsd,weight=h.avgUsd*h.shares;if(weight<=0)return;stockP+=(p/h.avgUsd-1)*weight;fxP+=(fx/(h.fxEntry||fx)-1)*weight;w+=weight});const stock=w?stockP/w*100:0,fxr=w?fxP/w*100:0,combined=(1+stock/100)*(1+fxr/100)-1;$('#thbReturnBody').innerHTML=[['Stock return',pct(stock)],['FX return',pct(fxr)],['Approx THB return',pct(combined*100)],['USD/THB now',fmt(fx,2)]].map(x=>`<div class="metric-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
async function loadCorrelations(){const syms=portfolio.slice(0,5).map(x=>x.symbol);if(syms.length<2){market.avgCorr=null;renderConcentration();return}const series=[];for(const s of syms){try{const j=await fetchChart(s,'1d'),r=[];for(let i=1;i<j.bars.length;i++)r.push(j.bars[i].close/j.bars[i-1].close-1);series.push(r.slice(-60))}catch{}}const corrs=[];for(let i=0;i<series.length;i++)for(let j=i+1;j<series.length;j++)corrs.push(corr(series[i],series[j]));market.avgCorr=corrs.length?corrs.reduce((a,b)=>a+b,0)/corrs.length:null;renderConcentration()}
function corr(a,b){const n=Math.min(a.length,b.length);if(n<5)return 0;a=a.slice(-n);b=b.slice(-n);const ma=a.reduce((x,y)=>x+y,0)/n,mb=b.reduce((x,y)=>x+y,0)/n;let num=0,da=0,db=0;for(let i=0;i<n;i++){const x=a[i]-ma,y=b[i]-mb;num+=x*y;da+=x*x;db+=y*y}return da&&db?num/Math.sqrt(da*db):0}

$('#paperBuyBtn').onclick=()=>{if(!A)return;const s=calcSizing().balanced;modal(`<h3>Paper Buy ${symbol}</h3><div class="form-grid" style="margin-top:15px"><label>Shares<input id="pShares" type="number" step="0.01" value="${Math.max(s.shares,1)}"></label><label>Entry USD<input id="pEntry" type="number" step="0.01" value="${fmt(A.last,2)}"></label><label>Stop<input id="pStop" type="number" step="0.01" value="${fmt(A.stop,2)}"></label><label>TP1<input id="pTp" type="number" step="0.01" value="${fmt(A.tp1,2)}"></label></div><button id="savePaper" class="primary" style="margin-top:12px">Simulate Buy</button>`);$('#savePaper').onclick=()=>{paper.push({id:now(),symbol,shares:+$('#pShares').value,entry:+$('#pEntry').value,stop:+$('#pStop').value,tp1:+$('#pTp').value,fxEntry:fx,rsi:A.rsi,date:now(),status:'open'});store('tensai-paper',paper);$('#modal').classList.add('hidden');renderPaper();toast('Paper position opened')}};
function renderPaper(){const open=paper.filter(x=>x.status==='open'),closed=journal;let pnl=0;open.forEach(x=>{const p=x.symbol===symbol?A?.last:x.last||x.entry;pnl+=(p-x.entry)*x.shares});$('#paperSummary').innerHTML=[['Open positions',open.length],['Open P&L',usd(pnl)],['Closed trades',closed.length],['Win rate',closed.length?pct(closed.filter(x=>x.pnl>0).length/closed.length*100):'—']].map(x=>`<div class="metric-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');$('#paperTrades').innerHTML=`<table><thead><tr><th>Symbol</th><th>Entry</th><th>Stop</th><th>TP1</th><th>Shares</th><th></th></tr></thead><tbody>${open.map(x=>`<tr><td>${x.symbol}</td><td>${usd(x.entry)}</td><td>${usd(x.stop)}</td><td>${usd(x.tp1)}</td><td>${fmt(x.shares,2)}</td><td><button data-close-paper="${x.id}">Close</button></td></tr>`).join('')}</tbody></table>`;$$('[data-close-paper]').forEach(b=>b.onclick=()=>closePaper(+b.dataset.closePaper));renderJournal()}
function closePaper(id){const x=paper.find(z=>z.id===id);if(!x)return;const price=x.symbol===symbol&&A?A.last:x.entry;const rec={...x,exit:price,exitDate:now(),pnl:(price-x.entry)*x.shares,pnlPct:(price/x.entry-1)*100};journal.push(rec);paper=paper.filter(z=>z.id!==id);store('tensai-paper',paper);store('tensai-journal',journal);renderPaper();toast('Paper trade closed')}
function renderJournal(){let insight=lang==='th'?'ยังไม่มีดีลปิดเพียงพอสำหรับวิเคราะห์พฤติกรรม':'Not enough closed trades for behavioral insights.';if(journal.length>=2){const wins=journal.filter(x=>x.pnl>0),avgRsi=journal.reduce((a,x)=>a+(x.rsi||50),0)/journal.length,avgHold=journal.reduce((a,x)=>a+(x.exitDate-x.date)/day,0)/journal.length;insight=lang==='th'?`Win rate ${fmt(wins.length/journal.length*100,0)}% · RSI ตอนเข้าเฉลี่ย ${fmt(avgRsi,1)} · ถือเฉลี่ย ${fmt(avgHold,1)} วัน${avgRsi>68?' · มีแนวโน้มเข้าเมื่อ momentum ร้อนเกินไป':''}`:`Win rate ${fmt(wins.length/journal.length*100,0)}% · average entry RSI ${fmt(avgRsi,1)} · average hold ${fmt(avgHold,1)} days${avgRsi>68?' · entries tend to occur when momentum is already hot':''}`;}setText('#journalInsight',insight);$('#journalTable').innerHTML=`<table><thead><tr><th>Symbol</th><th>Entry</th><th>Exit</th><th>P&L</th><th>RSI in</th></tr></thead><tbody>${journal.slice(-12).reverse().map(x=>`<tr><td>${x.symbol}</td><td>${usd(x.entry)}</td><td>${usd(x.exit)}</td><td class="${x.pnl>=0?'up':'down'}">${pct(x.pnlPct)}</td><td>${fmt(x.rsi,1)}</td></tr>`).join('')}</tbody></table>`}
function recordSignal(){if(!A)return;const hist=load('tensai-signal-log',[]),last=hist.at(-1);if(!last||last.symbol!==symbol||now()-last.time>6*3600000){hist.push({time:now(),symbol,price:A.last,score:A.opportunity,action:actionModel().code});store('tensai-signal-log',hist.slice(-100))}renderTrack()}
function renderTrack(){const h=load('tensai-signal-log',[]).filter(x=>x.symbol===symbol).slice(-8).reverse();$('#trackBody').innerHTML=h.length?h.map(x=>`<div class="metric-row"><span>${new Date(x.time).toLocaleDateString()} · ${x.action}</span><b>${usd(x.price)} · ${x.score}</b></div>`).join(''):`<div class="small">${lang==='th'?'ระบบจะเก็บสัญญาณที่คุณเปิดดูไว้เพื่อ audit ภายหลัง':'Viewed signals will be logged locally for later audit.'}</div>`}
function backtest(bs){const ix=indicators(bs);let trade=null,trades=[],equity=1,peak=1,maxDD=0;for(let i=55;i<bs.length;i++){const b=bs[i],rv=ix.r[i],mh=ix.hist[i],av=ix.a[i]||b.close*.02;if(trade){let exit=null;if(b.low<=trade.stop)exit=trade.stop;else if(b.high>=trade.tp)exit=trade.tp;else if(b.close<ix.e20[i])exit=b.close;if(exit){const r=(exit-trade.entry)/trade.entry;equity*=1+r;peak=Math.max(peak,equity);maxDD=Math.min(maxDD,(equity/peak-1)*100);trades.push({...trade,exit,ret:r*100});trade=null}}else if(b.close>ix.e20[i]&&ix.e20[i]>ix.e50[i]&&rv>=48&&rv<=68&&mh>0){trade={entry:b.close,stop:b.close-1.5*av,tp:b.close+2.5*av,date:b.time,rsi:rv}}}const wins=trades.filter(x=>x.ret>0),loss=trades.filter(x=>x.ret<=0),gp=wins.reduce((a,x)=>a+x.ret,0),gl=Math.abs(loss.reduce((a,x)=>a+x.ret,0));return{trades,winRate:trades.length?wins.length/trades.length*100:0,profitFactor:gl?gp/gl:gp?99:0,maxDD,total:(equity-1)*100,avgRR:trades.length?trades.reduce((a,x)=>a+x.ret,0)/trades.length:0}}
$('#runBacktest').onclick=async()=>{setText('#backtestBody','Running…');try{const j=await fetchChart(symbol,'1d'),b=backtest(j.bars);$('#backtestBody').innerHTML=[['Trades',b.trades.length],['Win rate',pct(b.winRate)],['Profit factor',fmt(b.profitFactor,2)],['Max drawdown',pct(b.maxDD)],['Compounded return',pct(b.total)],['Avg trade',pct(b.avgRR)]].map(x=>`<div class="metric-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');renderHistoricalTrack(b.trades)}catch(e){setText('#backtestBody',e.message)}};
function renderHistoricalTrack(trades){const t=trades.slice(-8).reverse();$('#trackBody').innerHTML=t.map(x=>`<div class="metric-row"><span>${new Date(x.date*1000).toLocaleDateString()} · BUY</span><b class="${x.ret>=0?'up':'down'}">${pct(x.ret)}</b></div>`).join('')}

